package main
import ("testing";"net";"time";"strings")
func TestSIPRoundTrip(t *testing.T) { msg:="INVITE sip:102@pbx.local SIP/2.0\r\nVia: SIP/2.0/UDP 127.0.0.1:6000;branch=z9hG4bKabc\r\nContent-Length: 5\r\n\r\nhello"; first,h,body:=splitSIP(msg); if method(first)!="INVITE"||sipUser(first)!="102"||body!="hello"{t.Fatal(first,body)}; _,_,again:=splitSIP(string(serialize(first,h,body)));if again!=body{t.Fatal(again)} }
func TestDigestAuthentication(t *testing.T) {p:=newPBX(Config{Domain:"pbx.local",Users:map[string]string{"101":"secret","102":"other"}},nil);uri:="sip:pbx.local";nc:="00000001";cnonce:="abc";response:=md5hex(md5hex("101:pbx.local:secret")+":"+p.nonce+":"+nc+":"+cnonce+":auth:"+md5hex("REGISTER:"+uri));h:=[][2]string{{"Authorization",`Digest username="101", realm="pbx.local", nonce="`+p.nonce+`", uri="`+uri+`", response="`+response+`", algorithm=MD5, qop=auth, nc=`+nc+`, cnonce="`+cnonce+`"`}}; if !p.authenticate(h,"101","REGISTER"){t.Fatal("valid digest rejected")};p.cfg.Users["101"]="bad";if p.authenticate(h,"101","REGISTER"){t.Fatal("wrong password accepted")} }
func TestInviteForwarding(t *testing.T) {s,_:=net.ListenUDP("udp",&net.UDPAddr{IP:net.IPv4(127,0,0,1)});defer s.Close();p:=newPBX(Config{Domain:"pbx.local",Users:map[string]string{"101":"a","102":"b"}},s);a,_:=net.ListenUDP("udp",&net.UDPAddr{IP:net.IPv4(127,0,0,1)});defer a.Close();b,_:=net.ListenUDP("udp",&net.UDPAddr{IP:net.IPv4(127,0,0,1)});defer b.Close();p.regs["101"]=Registration{a.LocalAddr().(*net.UDPAddr),"sip:101@127.0.0.1",time.Now().Add(time.Minute)};p.regs["102"]=Registration{b.LocalAddr().(*net.UDPAddr),"sip:102@127.0.0.1",time.Now().Add(time.Minute)};p.handle(a.LocalAddr().(*net.UDPAddr),[]byte("INVITE sip:102@pbx.local SIP/2.0\r\nVia: SIP/2.0/UDP 127.0.0.1:6000;branch=z9hG4bKx\r\nFrom: <sip:101@pbx.local>\r\nTo: <sip:102@pbx.local>\r\nCall-ID: test\r\nCSeq: 1 INVITE\r\nContent-Length: 0\r\n\r\n"));buf:=make([]byte,4096);b.SetReadDeadline(time.Now().Add(time.Second));n,_,e:=b.ReadFromUDP(buf);if e!=nil{t.Fatal(e)};first,h,_:=splitSIP(string(buf[:n]));if !strings.Contains(first,"sip:102@127.0.0.1")||len(headers(h,"Via"))!=2{t.Fatal(first,h)};p.handle(b.LocalAddr().(*net.UDPAddr),serialize("SIP/2.0 180 Ringing",h,""));a.SetReadDeadline(time.Now().Add(time.Second));n,_,e=a.ReadFromUDP(buf);if e!=nil{t.Fatal(e)};first,h,_=splitSIP(string(buf[:n]));if first!="SIP/2.0 180 Ringing"||len(headers(h,"Via"))!=1{t.Fatal(first,h)} }
